let speakOn=false,speakQueue=[],speakBusy=false,booting=true,speakWho='';
function speak(text,force,who){if(!('speechSynthesis' in window))return;if(!force&&!speakOn)return;speechSynthesis.cancel();speakQueue=[];speakBusy=false;speakWho=who||'';const clean=String(text).replace(/[*_#`]/g,'').replace(/\s+/g,' ').trim();const seg=clean.match(/[^。！？；\n]+[。！？；]?/g)||[clean];let buf='';seg.forEach(s=>{if((buf+s).length>90){if(buf)speakQueue.push(buf);buf=s}else buf+=s});if(buf)speakQueue.push(buf);speakNext()}
function speakNext(){if(speakBusy||!speakQueue.length)return;const u=new SpeechSynthesisUtterance(speakQueue.shift());u.lang='zh-CN';const vc=VOICE_CAST[speakWho]||{};u.rate=vc.r||.94;u.pitch=vc.p||1.02;u.volume=(state&&state.vol?state.vol.speak:90)/100;const v=speechSynthesis.getVoices().find(x=>/zh|Chinese|中文/i.test(x.lang+' '+x.name));if(v)u.voice=v;speakBusy=true;u.onend=u.onerror=()=>{speakBusy=false;speakNext()};speechSynthesis.speak(u)}
function announce(m){$('#live').textContent='';setTimeout(()=>$('#live').textContent=m,20);if(!booting&&speakOn)speak(m)}
