function tab(name){$$('.tab').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.tab===name)));$$('.panel').forEach(p=>p.hidden=p.id!==name);$('#tab-'+name).focus();const map={home:'开场',map:'关卡地图',story:'剧情关卡',codex:'资料库',time:'时间线',media:'跨媒体',stage:'角色舞台',gallery:'厚涂画廊',test:'人格测试',about:'版本与操作'};announce(map[name]+'页面');if(name==='map')renderMap();if(name==='codex')renderCodex();if(name==='time')renderTime();if(name==='media')renderMedia();if(name==='stage')renderStage();if(name==='gallery')renderGallery();if(name==='about')renderAbout();if(name==='story')renderQuest();pageSpeak()}
