const AE={ctx:null,master:null,mg:null,sg:null,timer:null,step:0,init(){if(this.ctx)return;const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;this.ctx=new AC();this.master=this.ctx.createGain();this.master.gain.value=.72;this.master.connect(this.ctx.destination);this.mg=this.ctx.createGain();this.mg.gain.value=.13;this.mg.connect(this.master);this.sg=this.ctx.createGain();this.sg.gain.value=.26;this.sg.connect(this.master)},tone(f,d,type,g,to){this.init();if(!this.ctx||$('#soundToggle').getAttribute('aria-pressed')!=='true')return;const t=this.ctx.currentTime,o=this.ctx.createOscillator(),a=this.ctx.createGain();o.type=type;o.frequency.setValueAtTime(f,t);if(to)o.frequency.exponentialRampToValueAtTime(to,t+d);a.gain.setValueAtTime(.0001,t);a.gain.exponentialRampToValueAtTime(g,t+.015);a.gain.exponentialRampToValueAtTime(.0001,t+d);o.connect(a);a.connect(this.sg);o.start(t);o.stop(t+d+.04)},noise(d,g){this.init();if(!this.ctx||$('#soundToggle').getAttribute('aria-pressed')!=='true')return;const n=Math.floor(this.ctx.sampleRate*d),b=this.ctx.createBuffer(1,n,this.ctx.sampleRate),c=b.getChannelData(0);for(let i=0;i<n;i++)c[i]=(Math.random()*2-1)*(1-i/n);const s=this.ctx.createBufferSource(),a=this.ctx.createGain(),f=this.ctx.createBiquadFilter();s.buffer=b;f.type='lowpass';f.frequency.value=900;a.gain.value=g;s.connect(f);f.connect(a);a.connect(this.sg);s.start()},sfx(n){const m={meow:()=>{this.tone(680,.16,'triangle',.34,520);setTimeout(()=>this.tone(520,.13,'sine',.22),110)},correct:()=>{this.tone(784,.13,'sine',.36);setTimeout(()=>this.tone(1046,.16,'triangle',.3),115);setTimeout(()=>this.tone(1318,.18,'sine',.26),230)},wrong:()=>{this.tone(190,.22,'sawtooth',.2,120)},unlock:()=>{this.tone(880,.1,'triangle',.3);setTimeout(()=>this.tone(1174,.12,'sine',.28),95);setTimeout(()=>this.tone(1568,.2,'sine',.24),190)},select:()=>this.tone(540,.07,'square',.15),collect:()=>{this.tone(1320,.08,'sine',.24);this.noise(.06,.05)},page:()=>this.noise(.12,.08),clear:()=>{this.tone(392,.2,'sine',.25);setTimeout(()=>this.tone(587,.22,'sine',.22),130)}};(m[n]||m.select)()},chord(fs,dur,g){this.init();if(!this.ctx)return;fs.forEach((f,i)=>{const t=this.ctx.currentTime+i*.04,o=this.ctx.createOscillator(),a=this.ctx.createGain();o.type=i%2?'triangle':'sine';o.frequency.value=f;a.gain.setValueAtTime(.0001,t);a.gain.exponentialRampToValueAtTime(g/5,t+.06);a.gain.exponentialRampToValueAtTime(.0001,t+dur);o.connect(a);a.connect(this.mg);o.start(t);o.stop(t+dur+.05)})},music(on){this.init();clearInterval(this.timer);if(!on||!this.ctx)return;const ch=[[261.6,329.6,392],[220,277.2,349.2],[196,246.9,293.7],[233.1,293.7,349.2]],arp=[523.3,659.3,784,587.3];const tick=()=>{if($('#musicToggle').getAttribute('aria-pressed')!=='true')return clearInterval(this.timer);this.chord(ch[this.step%4],1.7,.62);if(this.step%2===0)setTimeout(()=>this.chord([arp[(this.step/2)%4|0]],.5,.18),420);this.step++};tick();this.timer=setInterval(tick,1800)}};
