function currentQuest(){return DATA.quests.find(q=>!state.cleared.includes(q.id))||DATA.quests[DATA.quests.length-1]}
function renderMap(){
 let open='',doneHtml='',last='',doneCount=0;
 DATA.quests.forEach((q,i)=>{
  const done=state.cleared.includes(q.id),
        locked=i>state.cleared.length&&!state.cleared.includes(q.id-1),
        cur=i===state.cleared.length;
  const cls=done?'cleared':locked?'locked':cur?'current':'';
  const perf=perfLocked(q.id)?' perf-locked':'';
  const node='<button class="node '+cls+perf+'" '+(locked?'disabled aria-disabled="true"':'onclick="openQuest('+q.id+')"')
   +'><span class="dot">'+(done?'✅':locked?'🔒':cur?'🐾':'')+'</span>'
   +'<span class="num">'+q.id+'.</span> <b>'+esc(q.title)+'</b>'
   +'<small>'+esc(q.arc)+' · '+esc(q.src)+'</small>'
   +'<span class="tag '+(done?'green':'')+'">'+(done?'已通关':locked?'先完成前一关':'可进行')+'</span>'
   +(perfLocked(q.id)?'<span class="tag">敬请期待</span>':'')+'</button>';
  if(done){doneCount++;doneHtml+=node;return}
  if(q.chapter!==last){if(last)open+='</div>';last=q.chapter;
   open+='<h3 class="chapter">'+esc(q.chapter)+'</h3><div class="map">';}
  open+=node;
 });
 if(last)open+='</div>';
 const doneBox=doneCount
  ? '<details class="map-done" id="mapDone"><summary>✅ 已完成 '+doneCount+' / '+DATA.quests.length+' 关 · 点击展开回看</summary>'
   +'<div class="map">'+doneHtml+'</div></details>'
  : '<p class="muted map-empty">还没有通关记录，完成一关后这里会出现折叠回看区。</p>';
 $('#mapArea').innerHTML='<p class="muted map-intro">按故事先后分六章 · 点关卡进入 AVG 舞台 · 通关解锁词条</p>'
  +open+doneBox;
}
function unlock(list){const n=(list||[]).filter(id=>E(id)&&!state.unlocked.includes(id));state.unlocked.push(...n);save();if(n.length){AE.sfx('unlock');toast('新资料解锁：'+n.map(id=>E(id).name).join('、'))}}
function openQuest(id){if(id>1&&!state.cleared.includes(id-1)){toast('先完成上一关，哈士喵才能找到路。');return}state.active=id;save();tab('story')}
function renderQuest(){const q=Q(state.active)||currentQuest(),i=DATA.quests.indexOf(q),done=state.cleared.includes(q.id);const sp=q.spoiler===3?'<span class="tag red">完全剧透</span>':q.spoiler===2?'<span class="tag gold">中度剧透</span>':'<span class="tag">背景资料</span>';$('#quest').innerHTML='<p class="muted">第 '+q.id+' / '+DATA.quests.length+' 关 · '+esc(q.chapter)+' · '+esc(q.arc)+' · '+(done?'已通关':'进行中')+'</p><div class="progress" aria-label="关卡进度"><i style="width:'+(done?100:0)+'%"></i></div><div class="story"><div><h2>'+esc(q.title)+'</h2><div class="metaRow">'+sp+'<span class="tag">出处：'+esc(q.src)+'</span></div><p class="lead">'+esc(q.brief)+'</p><div class="card"><b>本关目标：</b>'+esc(q.goal)+'</div><div id="choiceArea" class="choices">'+q.choices.map((c,j)=>'<button class="choice" onclick="choose('+j+')"><b>'+(j+1)+'</b>. '+esc(c.t)+'</button>').join('')+'</div><div id="feedback" class="feedback" aria-live="assertive">'+(done?'这一关已经通关，可继续下一关，或去资料库查看解锁词条。':state.diff==='easy'?esc(q.tips):'请选择最准确的答案；幼喵难度会先显示提示。')+'</div><div class="modal-actions">'+(i>0?'<button class="small-btn" onclick="openQuest('+DATA.quests[i-1].id+')">← 上一关</button>':'')+(done&&i<DATA.quests.length-1?'<button class="small-btn bigBtn" onclick="openQuest('+DATA.quests[i+1].id+')">下一关 →</button>':'')+(done&&i===DATA.quests.length-1?'<button class="small-btn bigBtn" onclick="tab(\'about\')">查看版本边界 →</button>':'')+'<button class="small-btn" onclick="tab(\'map\')">返回地图</button></div></div><aside class="card"><h3>💡 提示 · 这一关看什么</h3><p>'+esc(q.tips)+'</p><h3>本关解锁</h3><p>'+(q.unlocks.length?q.unlocks.map(id=>'<span class="tag">'+esc(E(id)?.name||id)+'</span>').join(''):'无新增词条')+'</p><h3>资料边界</h3><p class="muted">详解只写已核实的卷章内容；创约14卷以后、中文版卷次与未核实的官方链接只登记、不补写。</p></aside></div>'}
