function choose(j){const q=Q(state.active)||currentQuest();if(state.cleared.includes(q.id))return;const c=q.choices[j];if(!c)return;AE.sfx('select');$$('.choice').forEach((b,k)=>{b.disabled=true;if(k===j)b.classList.add(c.ok?'correct':'wrong')});const head=c.ok?'✓ 答对啦，哈士喵尾巴转圈！':'✗ 差一点，先看线索：';$('#feedback').innerHTML='<b>'+head+'</b> '+esc(c.why);announce((c.ok?'正确。':'再想想。')+c.why);if(!c.ok&&state.diff==='hard'){mini.penalty=5;toast('原石狂人：小游戏时间减 5 秒。')}if(!c.ok){setTimeout(()=>{$$('.choice').forEach(b=>b.disabled=false);announce('可以再试一次。')},1500);return}setTimeout(()=>unlock(q.unlocks),350);setTimeout(()=>{finishQuest(q.id)},1000)}
