function renderCodex(){const cats=['全部'].concat(Array.from(new Set(DATA.entries.map(e=>e.cat))));$('#catFilter').innerHTML=cats.map(c=>'<option value="'+esc(c)+'">'+esc(c)+'（'+DATA.entries.filter(e=>c==='全部'||e.cat===c).length+'）</option>').join('');$('#catFilter').value=codexCat;$('#catChips').innerHTML=cats.map(c=>'<button class="chip" aria-pressed="'+(c===codexCat)+'" onclick="setCat(\''+esc(c)+'\')">'+esc(c)+'</button>').join('');drawEntryList()}
