function drawEntryList(){const kw=codexQ.trim().toLowerCase();const list=DATA.entries.filter(e=>(codexCat==='全部'||e.cat===codexCat)&&(!kw||(e.name+e.text+e.tags.join('')+e.src).toLowerCase().includes(kw)));$('#entryList').innerHTML=list.map(e=>{const on=state.unlocked.includes(e.id);return '<button role="option" aria-current="'+($('#entryDetail').dataset.id===e.id)+'" onclick="showEntry(\''+e.id+'\')"><b>'+(on?esc(e.name):'？？？')+'</b><br><small class="lock">'+(on?esc(e.cat)+' · '+esc(e.src):'第 '+e.unlock+' 关解锁')+'</small></button>'}).join('')||'<p class="muted">没有匹配的词条，换个关键词试试。</p>';if(!$('#entryDetail').dataset.id||!list.some(e=>e.id===$('#entryDetail').dataset.id))showEntry((list.find(e=>state.unlocked.includes(e.id))||list[0])?.id)}
function showEntry(id){const e=E(id);if(!e)return;if(!state.unlocked.includes(id)){toast('这格资料还没解锁，先完成对应关卡。');return}$('#entryDetail').dataset.id=id;const spoil=!state.spoiler&&e.spoiler===3;const tags=e.tags.map(t=>'<span class="tag">'+esc(t)+'</span>').join('');const sp=e.spoiler===3?'<span class="tag red">完全剧透</span>':e.spoiler===2?'<span class="tag gold">中度剧透</span>':'<span class="tag green">背景</span>';$('#entryDetail').innerHTML='<h3>'+esc(e.name)+'</h3><div class="metaRow"><span class="tag">'+esc(e.cat)+'</span>'+tags+sp+'<span class="tag">出处：'+esc(e.src)+'</span><span class="tag">第 '+e.unlock+' 关解锁</span></div><p'+(spoil?' class="warning"':'')+'>'+(spoil?'👓 剧透显示已关闭：此条为完全剧透内容，点顶部「剧透显示」即可查看。':esc(e.text))+'</p><p><b>相关词条：</b></p><div class="related">'+(e.links.filter(x=>E(x)&&state.unlocked.includes(x)).map(x=>'<button onclick="showEntry(\''+x+'\')">'+esc(E(x).name)+'</button>').join('')||'<span class="muted">继续闯关后开放</span>')+'</div>';$('#catFilter').value=codexCat;announce(e.name+'。'+(spoil?'剧透已隐藏。':e.text));if(!$('#codex').hidden)$('#entryDetail').focus()}
/* 时间线 / 跨媒体 */
function renderTime(){$('#timeline').innerHTML=DATA.timeline.map(a=>'<section class="arc"><h3>'+esc(a.era)+'</h3><p class="muted">'+esc(a.note)+'</p>'+a.events.map(ev=>'<div class="event"><span class="d">'+esc(ev.date)+(ev.approx?' · 约':'')+'</span><b>'+esc(ev.title)+'</b>：'+esc(ev.text)+'<br><span class="tag">'+esc(ev.src)+'</span></div>').join('')+'</section>').join('')+'<div class="card"><b>简易口诀：</b>一卷禁书 → 妹妹实验 → 暗部与世界危机 → 魔神与世界修正 → 新世界复原 → 仍在续写。每遇到看不懂的卷，先定位属于哪一段，再问「角色此时知道什么」。</div>'}
function renderMedia(){const main=DATA.media.filter(m=>m.main),other=DATA.media.filter(m=>!m.main);const card=m=>'<div class="mediaCard"><h3>'+esc(m.name)+'</h3><span class="tag '+(m.main?'gold':'')+'">'+esc(m.type)+'</span><span class="tag">'+esc(m.src)+'</span><p class="place">阅读位置：'+esc(m.place)+'</p><p>'+esc(m.note)+'</p></div>';$('#mediaArea').innerHTML='<h3 class="chapter">小说主线（按此顺序）</h3><div class="grid">'+main.map(card).join('')+'</div><h3 class="chapter">改编 · 外传 · 游戏 · 番外（单列，不并入卷序）</h3><div class="grid">'+other.map(card).join('')+'</div><div class="ok"><b>判读口诀：</b>看到「原创剧情 / 改编 / 删节」就单列；看到「SS / 22 REVERSE」才回到卷序里找位置。跨作品角色同台不等于主线事件。</div>'}
