/* 小游戏 */
/* ================== v0.31 · 资料碎片小游戏美术素材（本轮生成，全内嵌） ================== */
const MINI_SRC={bg:'./assets/ec6a2b6d48ae3530.webp',page:'./assets/493badcbe45f5025.webp',orb:'./assets/e316d019fb5bcf91.webp',player:'./assets/e757ef3a55775838.webp'};
const MINI_IMG={};
for(const k in MINI_SRC){const im=new Image();im.src=MINI_SRC[k];MINI_IMG[k]=im}

const mini={c:null,x:null,raf:0,last:0,keys:new Set,p:{x:400,y:392,r:19},sh:[],hz:[],got:0,time:30,penalty:0,run:false,over:false,qid:null,
 init(){this.c=$('#mini');this.x=this.c.getContext('2d');const ks=['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space','KeyW','KeyA','KeyS','KeyD'];
  window.addEventListener('keydown',e=>{if(this.run&&ks.includes(e.code)){e.preventDefault();this.keys.add(e.code);if(e.code==='Space')this.breath()}});
  window.addEventListener('keyup',e=>this.keys.delete(e.code));
  /* v0.33 · W3C Pointer Events：鼠标 / 触屏 / 触控笔同一条事件流，Phaser 也是这套 */
  const c=this.c,self=this;
  const toXY=e=>{const r=c.getBoundingClientRect();return{
    x:Math.max(19,Math.min(781,(e.clientX-r.left)/r.width*800)),
    y:Math.max(19,Math.min(431,(e.clientY-r.top)/r.height*450))};};
  c.addEventListener('pointerdown',e=>{if(!self.run||self.over)return;e.preventDefault();
    try{c.setPointerCapture(e.pointerId)}catch(_){}
    self.dragId=e.pointerId;self.target=toXY(e);
    const st=$('#gameStatus');if(st)st.textContent='拖动中';});
  c.addEventListener('pointermove',e=>{if(!self.run||self.dragId!==e.pointerId)return;e.preventDefault();self.target=toXY(e);});
  const stop=e=>{if(self.dragId!==e.pointerId)return;self.dragId=null;self.target=null;
    const st=$('#gameStatus');if(st)st.textContent='移动中';};
  c.addEventListener('pointerup',stop);c.addEventListener('pointercancel',stop);c.addEventListener('lostpointercapture',stop);
  c.addEventListener('dblclick',e=>{if(self.run){e.preventDefault();self.breath()}});
  },dragId:null,target:null,
 start(qid){this.qid=qid;this.run=true;this.over=false;this.got=0;this.time=(state.diff==='hard'?20:state.diff==='easy'?40:30)-this.penalty;this.penalty=0;this.p={x:400,y:392,r:19};this.sh=Array.from({length:5},()=>({x:60+Math.random()*680,y:70+Math.random()*300,r:14,got:false,ph:Math.random()*6}));this.hz=[];for(let i=0;i<6;i++)this.spawn();$('#modal').hidden=false;$('#mini').focus();$('#shardText').textContent='0 / 5';$('#timerText').textContent=Math.ceil(this.time);$('#gameStatus').textContent='移动中';announce('资料碎片小游戏开始。拖动哈士喵或按方向键移动，点哈气按钮或空格推开巡逻球，收集五片书页。');this.last=performance.now();cancelAnimationFrame(this.raf);this.raf=requestAnimationFrame(t=>this.loop(t))},
 spawn(){const left=Math.random()<.5,s=left?-20:820;this.hz.push({x:s,y:60+Math.random()*330,r:15+Math.random()*11,vx:(left?1:-1)*(62+Math.random()*52+state.cleared.length*3),vy:(Math.random()-.5)*34,life:1})},
 breath(){this.hz.forEach(h=>{if(Math.hypot(h.x-this.p.x,h.y-this.p.y)<118)h.life-=.85});AE.sfx('meow')},
 loop(t){const dt=Math.min(.033,(t-this.last)/1000);this.last=t;if(this.run&&!this.over){this.up(dt);this.draw();if(!this.over)this.raf=requestAnimationFrame(x=>this.loop(x))}},
 up(dt){this.time=Math.max(0,this.time-dt);const p=this.p,s=215;
  if(this.dragId!=null&&this.target){
    /* v0.33：拖动直接跟手（轻微缓动），不再限速 430px/s 导致拖不到位 */
    const dx=this.target.x-p.x,dy=this.target.y-p.y,f=Math.min(1,dt*18);
    p.x+=dx*f;p.y+=dy*f;
  }else{
    if(this.keys.has('ArrowLeft')||this.keys.has('KeyA'))p.x-=s*dt;if(this.keys.has('ArrowRight')||this.keys.has('KeyD'))p.x+=s*dt;
    if(this.keys.has('ArrowUp')||this.keys.has('KeyW'))p.y-=s*dt;if(this.keys.has('ArrowDown')||this.keys.has('KeyS'))p.y+=s*dt;
  }p.x=Math.max(p.r,Math.min(800-p.r,p.x));p.y=Math.max(p.r,Math.min(450-p.r,p.y));
 this.sh.forEach(g=>{if(!g.got&&Math.hypot(g.x-p.x,g.y-p.y)<p.r+g.r+12){g.got=true;this.got++;AE.sfx('collect');$('#shardText').textContent=this.got+' / 5';announce('收集 '+this.got+' 片资料碎片')}});
 this.hz.forEach(h=>{h.x+=h.vx*dt;h.y+=h.vy*dt;if(h.y<38||h.y>422)h.vy*=-1;if(h.life>0&&Math.hypot(h.x-p.x,h.y-p.y)<h.r+p.r){this.over=true;AE.sfx('wrong');$('#gameStatus').textContent='碰到巡逻球了，本关进度保留';announce('被巡逻球碰到了。整理已有线索，本关完成。');setTimeout(()=>this.end(),650)}});
 this.hz=this.hz.filter(h=>h.life>0&&h.x>-45&&h.x<845);if(Math.random()<dt*(.5+state.cleared.length*.045))this.spawn();$('#timerText').textContent=Math.ceil(this.time);if(this.time<=0){this.over=true;AE.sfx('unlock');$('#gameStatus').textContent='时间到，哈士喵把碎片拼好了';announce('时间到，但哈士喵把碎片拼好了。');setTimeout(()=>this.end(),700)}},
 end(){this.run=false;$('#modal').hidden=true;finishQuest(this.qid)},
 draw(){
 const x=this.x,I=MINI_IMG,t=performance.now();
 x.clearRect(0,0,800,450);
 /* ① 场景板：厚涂书库 + 漂浮书页，替掉原来的白蓝渐变与灰柱子 */
 if(I.bg&&I.bg.complete&&I.bg.naturalWidth)x.drawImage(I.bg,0,0,800,450);
 else{const g=x.createLinearGradient(0,0,0,450);g.addColorStop(0,'#14263c');g.addColorStop(1,'#08131f');x.fillStyle=g;x.fillRect(0,0,800,450)}
 /* 底部轻压暗，让道具轮廓更清楚 */
 const vg=x.createLinearGradient(0,0,0,450);vg.addColorStop(0,'#030a1600');vg.addColorStop(.70,'#030a1600');vg.addColorStop(1,'#030a16b0');x.fillStyle=vg;x.fillRect(0,0,800,450);
 /* ② 书页碎片：真素材 + 缓慢漂浮旋转 */
 this.sh.forEach(g2=>{if(g2.got)return;x.save();
  x.translate(g2.x,g2.y+Math.sin(t/480+g2.ph)*4);x.rotate(Math.sin(t/620+g2.ph)*.22);
  x.shadowColor='#ffd88a99';x.shadowBlur=16;
  if(I.page&&I.page.complete&&I.page.naturalWidth)x.drawImage(I.page,-21,-22,42,44);
  else{x.fillStyle='#fff6e0';x.fillRect(-14,-17,28,34)}
  x.restore()});
 /* ③ 巡逻符文球：真素材 + 缓慢自转 */
 this.hz.forEach(h=>{x.save();x.translate(h.x,h.y);x.rotate(t/1400);
  x.shadowColor='#ff7a5a88';x.shadowBlur=14;
  if(I.orb&&I.orb.complete&&I.orb.naturalWidth)x.drawImage(I.orb,-h.r,-h.r,h.r*2,h.r*2);
  else{x.fillStyle='#a33a48';x.beginPath();x.arc(0,0,h.r,0,Math.PI*2);x.fill()}
  x.restore()});
 /* ④ 玩家哈士喵：定稿画风的小猫层，替掉原来的圆脸贴纸 */
 const p=this.p;x.save();x.translate(p.x,p.y+Math.sin(t/300)*2);
 x.shadowColor='#000b';x.shadowBlur=12;
 if(I.player&&I.player.complete&&I.player.naturalWidth){var PB=fitBox(76,95,I.player.naturalWidth,I.player.naturalHeight,'contain');x.drawImage(I.player,-38+PB.x,-47+PB.y,PB.w,PB.h);}
 else{x.fillStyle='#f7f4ec';x.beginPath();x.arc(0,0,p.r,0,Math.PI*2);x.fill()}
 x.restore();
 /* ⑤ 哈气范围圈，改成暖金 */
 if(this.keys.has('Space')||this.breathFx>0){if(this.breathFx>0)this.breathFx-=1;x.strokeStyle='#ffe0a188';x.lineWidth=7;x.beginPath();x.arc(p.x,p.y,118,0,Math.PI*2);x.stroke()}
}
};
