$('#soundToggle').onclick=e=>{const on=e.currentTarget.getAttribute('aria-pressed')!=='true';e.currentTarget.setAttribute('aria-pressed',String(on));AE.init();AE.sfx('select');announce('音效'+(on?'开启':'关闭'))};
