/* 语音控制 */
const SR=window.SpeechRecognition||window.webkitSpeechRecognition;let rec=null;
function voiceLoop(){if(!SR||$('#voiceToggle').getAttribute('aria-pressed')!=='true')return;try{rec=new SR();rec.lang='zh-CN';rec.continuous=false;rec.interimResults=false;rec.maxAlternatives=3;rec.onresult=ev=>{const r=ev.results[0];const text=Array.from({length:r.length},(_,i)=>r[i].transcript).filter(Boolean).join(' ');handleVoice(text)};rec.onerror=()=>{if($('#voiceToggle').getAttribute('aria-pressed')==='true')setTimeout(voiceLoop,1300)};rec.onend=()=>{if($('#voiceToggle').getAttribute('aria-pressed')==='true')setTimeout(voiceLoop,500)};rec.start()}catch(err){toast('无法启动语音识别，请用点按或键盘操作。')}}
function handleVoice(t){toast('听到：“'+t+'”');const has=(...xs)=>xs.some(x=>t.includes(x));const cur=Q(state.active)||currentQuest(),idx=DATA.quests.indexOf(cur);
 if(has('地图'))tab('map');else if(has('资料','词条','百科'))tab('codex');else if(has('时间线'))tab('time');else if(has('跨媒体','改编','外传'))tab('media');else if(has('测试','人格'))tab('test');else if(has('舞台','角色','换装'))tab('stage');else if(has('画廊','抠图','背景','质量','品红','猫身','预览卡','少一块'))tab('gallery');else if(has('下一句','继续对白','跳过对白'))vnNext();else if(has('天晴','晴天','太阳','鸟叫'))setWeather('sunny');else if(has('下雨','雨声'))setWeather('rain');else if(has('夜晚','星星','虫鸣'))setWeather('night');else if(has('下雪','红雪'))setWeather('redsnow');else if(has('起雾','雾'))setWeather('fog');else if(has('起风','风声'))setWeather('wind');else if(has('关于','版本','操作','来源'))tab('about');else if(has('开场','首页'))tab('home');
 else if(/第\s*[一二三四五六七八九十0-9]+\s*关/.test(t)){const m=t.match(/第\s*([一二三四五六七八九十0-9]+)\s*关/);const cn={'一':1,'二':2,'三':3,'四':4,'五':5,'六':6,'七':7,'八':8,'九':9,'十':10};let n=cn[m[1]]||parseInt(m[1],10);if(/二十|廿/.test(m[1]))n=20+ (cn[m[1].replace(/二十|廿/,'')]||0);if(/三十/.test(m[1]))n=30;if(n>=1&&n<=DATA.quests.length)openQuest(n)}else if(has('搜索','查找')){const kw=t.replace(/.*?(搜索|查找)/,'').trim();if(kw){codexQ=kw;$('#entrySearch').value=kw;tab('codex');drawEntryList();announce('搜索：'+kw)}}
 else if(has('下一关','开始','继续')){if(idx<DATA.quests.length-1&&state.cleared.includes(cur.id))openQuest(DATA.quests[idx+1].id);else openQuest(cur.id)}else if(has('上一关')){if(idx>0)openQuest(DATA.quests[idx-1].id)}else if(has('换角色','下一个角色','切换角色')){const seq=CHARS.chars.map(c=>c.id);setChar(seq[(seq.indexOf(state.char)+1)%seq.length])}else if(has('朗读','念一下'))pageSpeak();else if(has('停止','安静','别念')){speechSynthesis.cancel();speakQueue=[];speakBusy=false}else if(has('音乐'))$('#musicToggle').click();else if(has('音效'))$('#soundToggle').click();else if(has('剧透'))$('#spoilerToggle').click();else if(has('重玩','重新开始'))$('#resetBtn').click();
 else if(/选择\s*[一二三四1-4]/.test(t)){const m=t.match(/选择\s*([一二三四1-4])/);const mp={一:0,二:1,三:2,四:3};choose(mp[m[1]]??parseInt(m[1],10)-1)}else{const m=t.match(/[一二三四1-4]/);if(m&&!$('#story').hidden){const mp={一:0,二:1,三:2,四:3};choose(mp[m[0]]??parseInt(m[0],10)-1)}}}
