const WX_TYPES=['sunny','rain','night','snow','redsnow','fog','wind','off'];
const WX_NAME={sunny:'☀ 天晴 · 鸟叫',rain:'🌧 下雨 · 雨声',night:'🌙 夜晚 · 虫鸣',snow:'❄ 下雪 · 风声',redsnow:'🌹 红雪 · 风声',fog:'🌫 起雾 · 低鸣',wind:'🍃 起风 · 风声',off:'⏹ 静止 / 静音',auto:'自动（随关卡）'};
/* 30 关天气：按卷次氛围映射，可在工具栏手动覆盖 */
const WX_MAP=['night','fog','rain','sunny','sunny','sunny','fog','wind','night','wind',
              'rain','snow','night','wind','rain','sunny','fog','wind','night','sunny',
              'snow','sunny','sunny','rain','redsnow','sunny','sunny','sunny','sunny','night'];
function weatherFor(q){return WX_MAP[(q.id-1)%WX_MAP.length]||'sunny'}
function currentWeather(){const w=state.weather||'auto';return w==='auto'?weatherFor(Q(state.active)||currentQuest()):w}
/* 每关登场的角色（只复用已有 21 层，按 30 关配图总表的主次排位） */
const CAST_MAP={
 1:['index','touma'],2:['touma','styl'],3:['misaka','accelerator'],4:['touma','index'],
 5:['index','kanzaki'],6:['misaka','kuroko'],7:['touma','rightfire'],8:['touma','accelerator'],
 9:['hamazura','mugino','kakine'],10:['kanzaki','touma'],11:['rightfire','touma'],
 12:['touma','accelerator','rightfire'],13:['touma','accelerator','hamazura'],
 14:['othinus','touma'],15:['touma','rightfire'],16:['othinus'],17:['othinus','index'],
 18:['shangli','sakuyo'],19:['index','touma'],20:['index','librarian'],21:['touma','index'],
 22:['alice','touma'],23:['alice','touma'],24:['index','misaka','shokuhou'],
 25:['kanzaki','base'],26:['base','librarian'],27:['index','touma','styl'],
 28:['misaka','kuroko','shokuhou'],29:['accelerator','lastorder','mugino'],30:['base','librarian']};
function questCast(q){return (CAST_MAP[q.id]||['base']).filter(id=>ART.chars[id])}

/* ---------- 天气动画引擎：canvas 逐帧绘制 ---------- */
const WX={
 cv:null,cx:null,type:'sunny',t:0,raf:0,dpr:1,parts:[],birds:[],stars:[],flash:0,reduce:false,
 boot(){this.reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;this.loop()},
 pick(){const all=$$('.vn-fx');let best=null;for(const c of all){const p=c.closest('.vn,.stage');if(p&&!p.closest('[hidden]')&&c.getClientRects().length){best=c;break}}return best},
 size(c){this.dpr=Math.min(2,devicePixelRatio||1);const w=c.clientWidth,h=c.clientHeight;if(!w||!h)return false;if(c.width!==Math.round(w*this.dpr)||c.height!==Math.round(h*this.dpr)){c.width=Math.round(w*this.dpr);c.height=Math.round(h*this.dpr)}return true},
 seed(type,w,h){
  this.parts=[];this.birds=[];this.stars=[];
  const R=(a,b)=>a+Math.random()*(b-a);
  if(type==='rain'){for(let i=0;i<150;i++)this.parts.push({x:R(0,w),y:R(0,h),l:R(9,26),v:R(680,1180),a:R(.16,.5)})}
  else if(type==='snow'||type==='redsnow'){for(let i=0;i<110;i++)this.parts.push({x:R(0,w),y:R(0,h),r:R(1.1,3.6),v:R(22,64),ph:R(0,6.3),sw:R(9,32)})}
  else if(type==='night'){for(let i=0;i<95;i++)this.stars.push({x:R(0,w),y:R(0,h*.72),r:R(.5,1.7),ph:R(0,6.3)});this.parts.push({x:R(0,w),y:R(0,h*.4),v:R(300,520)})}
  else if(type==='fog'){for(let i=0;i<7;i++)this.parts.push({x:R(-w*.4,w),y:R(h*.12,h*.8),w:R(w*.35,w*.85),h:R(24,78),v:R(7,22),a:R(.05,.15)})}
  else if(type==='wind'){for(let i=0;i<46;i++)this.parts.push({x:R(0,w),y:R(0,h),l:R(22,110),v:R(230,520),a:R(.08,.30),ph:R(0,6.3)})}
  else if(type==='sunny'){for(let i=0;i<34;i++)this.parts.push({x:R(0,w),y:R(0,h*.85),r:R(1,3.4),v:R(5,18),ph:R(0,6.3)});
   for(let i=0;i<3;i++)this.birds.push({x:R(-w*.2,w*.8),y:R(h*.08,h*.34),v:R(24,52),s:R(.7,1.35),ph:R(0,6.3)})}
 },
 setType(t){if(!WX_TYPES.includes(t))t='sunny';if(t===this.type&&this.cv)return;this.type=t;this.flash=0;
  const c=this.pick()||this.cv;if(c&&this.size(c)){this.cv=c;this.cx=null;this.seed(t,c.clientWidth,c.clientHeight)}
  AE.amb&&AE.amb.start(t==='off'?null:t)},
 loop(){const step=()=>{const c=this.pick();
   if(c!==this.cv){this.cv=c;this.cx=null;if(c&&this.size(c))this.seed(this.type,c.clientWidth,c.clientHeight)}
   if(c&&this.size(c))this.draw(c);this.raf=requestAnimationFrame(step)};
  cancelAnimationFrame(this.raf);this.loop=()=>{};step()},
 draw(c){const x=c.getContext('2d'),w=c.clientWidth,h=c.clientHeight,d=this.dpr,t=this.type;
  x.setTransform(d,0,0,d,0,0);x.clearRect(0,0,w,h);
  if(!this.reduce)this.t+=1/60;const T=this.t;
  if(t==='sunny'){
   const g=x.createRadialGradient(w*.30,h*.16,4,w*.30,h*.16,h*.62);
   g.addColorStop(0,'#ffe6a8aa');g.addColorStop(.28,'#ffd77a44');g.addColorStop(1,'#ffd77a00');
   x.fillStyle=g;x.fillRect(0,0,w,h);
   x.save();x.translate(w*.30,h*.16);x.rotate(T*.06);x.strokeStyle='#fff0bf38';x.lineWidth=2;
   for(let i=0;i<12;i++){x.rotate(Math.PI/6);x.beginPath();x.moveTo(h*.07,0);x.lineTo(h*.46,0);x.stroke()}x.restore();
   x.fillStyle='#fff6d9';x.beginPath();x.arc(w*.30,h*.16,h*.045,0,7);x.fill();
   for(const p of this.parts){const yy=(p.y-T*p.v)%h,xx=p.x+Math.sin(T*.7+p.ph)*11;x.globalAlpha=.28+.22*Math.sin(T*1.6+p.ph);x.fillStyle='#fff4cf';x.beginPath();x.arc(xx,(yy+h)%h,p.r,0,7);x.fill()}
   x.globalAlpha=1;
   for(const b of this.birds){if(!this.reduce)b.x+=b.v/60;if(b.x>w+h*.1){b.x=-h*.1;b.y=Math.max(h*.06,b.y-h*.04)}
    const flap=Math.sin(T*7+b.ph)*.42+ .38;x.strokeStyle='#233246b0';x.lineWidth=2.1;
    x.save();x.translate(b.x,b.y);x.scale(b.s,b.s);
    x.beginPath();x.moveTo(-11,0);x.quadraticCurveTo(-5,-flap*12,0,0);x.quadraticCurveTo(5,-flap*12,11,0);x.stroke();x.restore()}
  }else if(t==='rain'){
   x.fillStyle='#0a1830';x.globalAlpha=.20;x.fillRect(0,0,w,h);x.globalAlpha=1;
   for(const p of this.parts){if(!this.reduce){p.y+=p.v/60;p.x+=p.v/300;if(p.y>h){p.y=-p.l;p.x=Math.random()*w}}
    x.strokeStyle='rgba(198,226,255,'+p.a+')';x.lineWidth=1.15;x.beginPath();x.moveTo(p.x,p.y);x.lineTo(p.x-p.l*.30,p.y+p.l);x.stroke()}
   x.strokeStyle='#cfe6ff55';x.lineWidth=1;
   for(let i=0;i<7;i++){const cx=((i*197+T*40)%(w+80))-40,cy=h*.86+Math.sin(T*2+i)*3;x.beginPath();x.ellipse(cx,cy,10+((T*14+i*9)%22),2.4,0,0,7);x.stroke()}
   if(this.flash>0){x.fillStyle='rgba(226,240,255,'+(this.flash*.42)+')';x.fillRect(0,0,w,h);this.flash-=1}
   else if(Math.random()<.0016)this.flash=7;
  }else if(t==='snow'||t==='redsnow'){
   const col=t==='redsnow'?'#ff9aa6':'#ffffff';
   for(const p of this.parts){if(!this.reduce){p.y+=p.v/60;p.ph+=.012;if(p.y>h+4){p.y=-4;p.x=Math.random()*w}}
    const xx=p.x+Math.sin(p.ph)*p.sw;x.globalAlpha=.42+.4*Math.sin(p.ph*2);x.fillStyle=col;
    x.beginPath();x.arc(xx,p.y,p.r,0,7);x.fill()}x.globalAlpha=1;
   if(t==='redsnow'){const g=x.createLinearGradient(0,0,0,h);g.addColorStop(0,'#5a142000');g.addColorStop(1,'#7a1d2a55');x.fillStyle=g;x.fillRect(0,0,w,h)}
  }else if(t==='night'){
   x.fillStyle='#050d1c';x.globalAlpha=.22;x.fillRect(0,0,w,h);x.globalAlpha=1;
   for(const s of this.stars){x.globalAlpha=.25+.72*Math.abs(Math.sin(T*1.3+s.ph));x.fillStyle='#dcecff';x.beginPath();x.arc(s.x,s.y,s.r,0,7);x.fill()}x.globalAlpha=1;
   const m=this.parts[0];if(m){if(!this.reduce){m.x+=m.v/60;m.y+=m.v/230;if(m.x>w||m.y>h*.6){m.x=-30;m.y=Math.random()*h*.25}}
    const g=x.createLinearGradient(m.x,m.y,m.x-70,m.y-24);g.addColorStop(0,'#ffffff00');g.addColorStop(1,'#dcecffcc');x.strokeStyle=g;x.lineWidth=1.6;x.beginPath();x.moveTo(m.x,m.y);x.lineTo(m.x-70,m.y-24);x.stroke()}
  }else if(t==='fog'){
   for(const p of this.parts){if(!this.reduce)p.x+=p.v/60;if(p.x>w)p.x=-p.w;
    const g=x.createLinearGradient(p.x,0,p.x+p.w,0);g.addColorStop(0,'#dce8f500');g.addColorStop(.5,'rgba(220,232,245,'+p.a+')');g.addColorStop(1,'#dce8f500');
    x.fillStyle=g;x.fillRect(p.x,p.y,p.w,p.h)}
  }else if(t==='wind'){
   for(const p of this.parts){if(!this.reduce)p.x+=p.v/60;if(p.x>w+120)p.x=-120;
    const yy=p.y+Math.sin(T*2+p.ph)*9;x.strokeStyle='rgba(220,238,255,'+p.a+')';x.lineWidth=1.2;
    x.beginPath();x.moveTo(p.x,yy);x.lineTo(p.x+p.l,yy-2);x.stroke()}
   for(let i=0;i<5;i++){const lx=((i*263+T*250)%(w+60))-30,ly=h*.22+i*h*.13+Math.sin(T*1.4+i)*22;
    x.save();x.translate(lx,ly);x.rotate(T*1.7+i);x.fillStyle='#c8b98a66';x.beginPath();x.ellipse(0,0,7,3,0,0,7);x.fill();x.restore()}
  }
 }
};

/* ---------- 场景联动音效：鸟叫 / 雨声 / 虫鸣 / 风声 / 低鸣 ---------- */
AE.ag=null;
AE.amb={
 timer:null,type:null,alive:false,
 gain(){if(!AE.ctx)return null;if(!AE.ag){AE.ag=AE.ctx.createGain();AE.ag.gain.value=.17;AE.ag.connect(AE.master)}return AE.ag},
 chirp(){if(!AE.ctx||!this.alive)return;const g=this.gain();if(!g)return;const t=AE.ctx.currentTime;
  [0,.085,.17].forEach((off,i)=>{const o=AE.ctx.createOscillator(),a=AE.ctx.createGain(),f=[2100,2550,2280][i];
   o.type='sine';o.frequency.setValueAtTime(f*.78,t+off);o.frequency.exponentialRampToValueAtTime(f,t+off+.035);o.frequency.exponentialRampToValueAtTime(f*.86,t+off+.10);
   a.gain.setValueAtTime(.0001,t+off);a.gain.exponentialRampToValueAtTime(.16,t+off+.018);a.gain.exponentialRampToValueAtTime(.0001,t+off+.12);
   o.connect(a);a.connect(g);o.start(t+off);o.stop(t+off+.15)})},
 drop(){if(!AE.ctx||!this.alive)return;const g=this.gain();if(!g)return;const t=AE.ctx.currentTime,o=AE.ctx.createOscillator(),a=AE.ctx.createGain();
  o.type='sine';o.frequency.setValueAtTime(900+Math.random()*950,t);o.frequency.exponentialRampToValueAtTime(340,t+.045);
  a.gain.setValueAtTime(.0001,t);a.gain.exponentialRampToValueAtTime(.035,t+.008);a.gain.exponentialRampToValueAtTime(.0001,t+.07);
  o.connect(a);a.connect(g);o.start(t);o.stop(t+.09)},
 windNoise(dur){if(!AE.ctx||!this.alive)return;const g=this.gain();if(!g)return;const n=Math.floor(AE.ctx.sampleRate*dur),b=AE.ctx.createBuffer(1,n,AE.ctx.sampleRate),c=b.getChannelData(0);
  for(let i=0;i<n;i++)c[i]=(Math.random()*2-1)*Math.sin(Math.PI*i/n);
  const s=AE.ctx.createBufferSource(),f=AE.ctx.createBiquadFilter(),a=AE.ctx.createGain();s.buffer=b;f.type='bandpass';f.frequency.value=420;f.Q.value=.6;
  a.gain.value=.30;s.connect(f);f.connect(a);a.connect(g);s.start()},
 cricket(){if(!AE.ctx||!this.alive)return;const g=this.gain();if(!g)return;const t=AE.ctx.currentTime;
  for(let i=0;i<3;i++){const o=AE.ctx.createOscillator(),a=AE.ctx.createGain();o.type='triangle';o.frequency.value=4200+i*90;
   a.gain.setValueAtTime(.0001,t+i*.09);a.gain.exponentialRampToValueAtTime(.045,t+i*.09+.01);a.gain.exponentialRampToValueAtTime(.0001,t+i*.09+.06);
   o.connect(a);a.connect(g);o.start(t+i*.09);o.stop(t+i*.09+.08)}},
 low(){if(!AE.ctx||!this.alive)return;const g=this.gain();if(!g)return;const t=AE.ctx.currentTime,o=AE.ctx.createOscillator(),a=AE.ctx.createGain();
  o.type='sine';o.frequency.value=88;a.gain.setValueAtTime(.0001,t);a.gain.exponentialRampToValueAtTime(.10,t+.5);a.gain.exponentialRampToValueAtTime(.0001,t+2.4);
  o.connect(a);a.connect(g);o.start(t);o.stop(t+2.5)},
 tick(){if(!this.alive||!this.type)return;const on=()=>$('#soundToggle').getAttribute('aria-pressed')==='true';
  const t=this.type,r=Math.random();
  if(on()&&AE.ctx){
   if(t==='sunny'){if(r<.82)this.chirp();else this.windNoise(.7)}
   else if(t==='rain'){this.drop();if(r<.05)AE.noise(.35,.018)}
   else if(t==='night'){if(r<.7)this.cricket();else this.windNoise(.8)}
   else if(t==='snow'||t==='redsnow'||t==='wind'){this.windNoise(.9)}
   else if(t==='fog'){if(r<.5)this.low();else this.windNoise(1.1)}
  }
  const delay=t==='rain'?90+Math.random()*150:t==='sunny'?2600+Math.random()*4200:t==='night'?1700+Math.random()*2600:t==='fog'?3600+Math.random()*3000:1200+Math.random()*1900;
  this.timer=setTimeout(()=>this.tick(),delay)},
 start(type){clearTimeout(this.timer);this.type=type;this.alive=!!type&&type!=='off';if(!this.alive)return;
  if(!AE.ctx)return;AE.ctx.resume&&AE.ctx.resume();this.gain();this.tick()},
 stop(){clearTimeout(this.timer);this.alive=false;this.type=null}
};
