let vnLines=[],vnStep=0,vnTimer=null,vnDone=false;
function buildDialog(q){
 const brief=String(q.brief).trim();const parts=brief.match(/[^。！？]+[。！？]?/g)||[brief];
 const mid=Math.max(1,Math.ceil(parts.length/2));
 const a=parts.slice(0,mid).join('').trim(),b=parts.slice(mid).join('').trim();
 const L=[
  {name:'导览员 · 禁书目录',text:'第 '+q.id+' 关｜'+q.arc+'　《'+q.title+'》'},
  {name:'哈士喵',text:a||'（哈士喵竖起耳朵，把资料卡摊了一地。）'}
 ];
 if(b)L.push({name:'哈士喵',text:b});
 L.push({name:'导览员 · 禁书目录',text:'本关目标：'+q.goal+'　｜　出处：'+q.src});
 if(state.diff==='easy')L.push({name:'哈士喵',text:'幼喵提示：'+q.tips});
 if(state.cleared.includes(q.id))L.push({name:'结业馆长',text:'这一关已经通关。可以回看对白、翻选项，或直接去下一关。'});
 return L;
}
function vnCastHtml(q){const ids=questCast(q);return ids.map((id,i)=>{
 const c=CHAR_BY_ID[id]||CHARS.chars[0],cls=i===0?'vn-char':('vn-char '+(i===1?'sub':'sub2'));
 const alt=esc(c.name)+'：'+esc(c.expression)+'；'+esc(c.pose);
 const br=ART.breath&&ART.breath[id];
 if(br)return '<span class="vn-actor '+cls+'" role="img" aria-label="'+alt+'（双帧呼吸循环）">'
  +'<img class="bf a" src="'+br.a+'" alt=""><img class="bf b" src="'+br.b+'" alt=""></span>';
 return '<img class="'+cls+' breathe-css" src="'+(ART.chars[id]||ART.chars.base)+'" alt="'+alt+'">';
 }).join('')}
function vnStopType(){if(vnTimer){clearInterval(vnTimer);vnTimer=null}}
function vnType(el,text){vnStopType();if(!el)return;const box=el.closest('.vn-dialog');
 const full=box&&box.querySelector('.vn-full');if(full)full.textContent=text;
 el.textContent='';let i=0;const caret=document.createElement('span');caret.className='vn-caret';caret.setAttribute('aria-hidden','true');
 if(WX.reduce){el.textContent=text;return}
 vnTimer=setInterval(()=>{i+=1;el.textContent=text.slice(0,i);if(i>=text.length){vnStopType();el.appendChild(caret)}},26)}
function vnComplete(){vnStopType();const el=$('#vnText');if(!el)return;const full=$('#vnFull');if(full)el.textContent=full.textContent}
function vnNext(){if(vnTimer){vnComplete();return}vnStep++;vnRender()}
function vnSkipAll(){vnStopType();vnStep=vnLines.length;vnRender()}
function vnRender(){const q=Q(state.active)||currentQuest();const box=$('#vnDialog');if(!box)return;
 const name=box.querySelector('.vn-name'),txt=$('#vnText'),ctl=$('#vnCtl'),prog=$('#vnProg');
 vnStopType();
 if(vnStep<vnLines.length){
  const L=vnLines[vnStep];box.classList.remove('mode-choice');name.textContent=L.name;txt.textContent='';vnType(txt,L.text);
  ctl.innerHTML='<button class="go" onclick="vnNext()">下一句 ▶</button><button onclick="vnSkipAll()">⏭ 跳到选项</button>'
    +'<button onclick="goFull()">⛶ 横屏</button>' +'<button onclick="vnTip()">💡 提示</button>'
   +'<span class="vn-hint">点画面 / 空格也可推进 · '+(vnStep+1)+' / '+vnLines.length+'</span>';
  if(prog)prog.style.width=Math.round(vnStep/vnLines.length*100)+'%';
  voiceAct(L.name,L.text);
 }else{
  /* v0.31：题干不再用气泡，压成一行放在提示按钮上方 */
  box.classList.add('mode-choice');name.textContent='';txt.innerHTML='';
  const full=box.querySelector('.vn-full');if(full)full.textContent='请从四个选项中选出最准确的一条。';
  ctl.innerHTML='<div class="vn-judge" id="vnJudge">'+judgeDefault()+'</div>'
   +'<div class="vn-tools"><button onclick="goFull()">⛶ 横屏</button>'+'<button onclick="vnTip()">💡 提示</button>'+'<button onclick="vnStep=0;vnRender()">↺ 重看对白</button>'+'<span class="vn-hint">键盘 1–4 也可选择</span></div>'
   +'<div class="vn-choices">'+q.choices.map((c,j)=>'<button class="vn-choice" onclick="choose('+j+')"><b>'+(j+1)+'</b>'+esc(c.t)+'</button>').join('')+'</div>';
  if(prog)prog.style.width='100%';
 }
 const hud=$('#vnWx');if(hud)hud.textContent=WX_NAME[currentWeather()]||'';
}
function vnTip(){const q=Q(state.active)||currentQuest();vnFeedback('<b>💡 提示 · 哈士喵的线索</b><br>'+esc(q.tips))}
function vnFeedback(html){vnStopType();const box=$('#vnDialog');if(!box)return;
 const name=box.querySelector('.vn-name'),txt=$('#vnText'),ctl=$('#vnCtl'),full=box.querySelector('.vn-full');
 const plain=String(html).replace(/<[^>]+>/g,'').replace(/&[a-z]+;/g,' ');
 name.textContent='💬 哈士喵的判读';box.classList.add('mode-choice');txt.innerHTML=html;if(full)full.textContent=plain;
 if(ctl&&!ctl.querySelector('#vnBack'))ctl.insertAdjacentHTML('afterbegin','<button id="vnBack" class="go" onclick="vnStep=0;vnRender()">↩ 回到对白</button>');
 if(speakOn)speak(plain)}

