/* ---------- 重写答题：反馈也进气泡 ---------- */
function choose(j){
 const q=Q(state.active)||currentQuest();const c=q.choices[j];if(!c)return;
 const done=state.cleared.includes(q.id);
 AE.sfx(done?'select':'select');
 $$('.vn-choice').forEach((b,k)=>{if(k===j)b.classList.add(c.ok?'correct':'wrong')});
 if(done){vnFeedback('<b>【回顾】'+esc(c.t)+'</b><br>'+esc(c.why));return}
 const head=c.ok?'✓ 答对啦，哈士喵尾巴转圈！':'✗ 差一点，先看线索：';
 vnFeedback('<b>'+head+'</b> '+esc(c.why));
 announce((c.ok?'正确。':'再想想。')+c.why);
 if(!c.ok){
  if(state.diff==='hard'){mini.penalty=5;toast('原石狂人：小游戏时间减 5 秒。')}
  setTimeout(()=>{$$('.vn-choice').forEach(b=>{b.disabled=false;b.className='vn-choice'});vnFeedback('<b>🔎 线索：</b>'+esc(q.tips)+'<br>再选一次吧。')},1600);
  return;
 }
 AE.sfx('correct');
 setTimeout(()=>unlock(q.unlocks),350);
 setTimeout(()=>{finishQuest(q.id)},1100)
}

