/* ============ v0.31 · 横屏（CSS 伪横屏，不依赖浏览器 API） ============ */
function visibleStage(){return $$('.vn,.stage').find(x=>!x.closest('.panel[hidden]'))||$('#vnStage')||$('#homeStage')}
function ensureLsBar(){
 let bar=$('#lsBar');
 if(!bar){
  bar=document.createElement('div');bar.id='lsBar';bar.className='ls-bar';
  bar.innerHTML='<button type="button" class="ls-exit">↩ 退出横屏</button>'
   +'<button type="button" class="ls-flip">↻ 换个方向</button>';
  bar.querySelector('.ls-exit').onclick=exitLandscape;
  bar.querySelector('.ls-flip').onclick=()=>{document.body.classList.toggle('ls-flip');toast('↻ 已切换旋转方向')};
  document.body.appendChild(bar);
 }
 return bar;
}
function applyLandscape(el){
 if(!el)return;
 document.body.classList.add('ls-mode');
 $$('.ls-target').forEach(x=>x.classList.remove('ls-target'));
 el.classList.add('ls-target');
 ensureLsBar();   /* 控制条在旋转容器外，两个旋转方向都能点 */
 /* 画布尺寸已变，强制重新 seed */
 try{WX.type=null;WX.setType(currentWeather())}catch(e){}
}
function exitLandscape(){
 document.body.classList.remove('ls-mode');document.body.classList.remove('ls-flip');
 $$('.ls-target').forEach(x=>x.classList.remove('ls-target'));
 const bar=$('#lsBar');if(bar)bar.remove();
 try{if(document.fullscreenElement)document.exitFullscreen()}catch(e){}
 try{WX.type=null;WX.setType(currentWeather())}catch(e){}
 toast('↩ 已退出横屏');
}
function enterLandscape(){
 /* 没在剧情页就先切过去，保证舞台 DOM 存在 */
 document.body.classList.add('ls-mode');
 if(!$('#vnStage')||$('#story').hidden){try{tab('story')}catch(e){}}
 const el=$('#vnStage')||visibleStage();
 applyLandscape(el);
 toast('⛶ 横屏舞台已就位 · 把手机横过来看；方向不对点「↻ 换个方向」（此环境不能自动旋转系统）');
}
function goFull(){
 if(document.body.classList.contains('ls-mode')){exitLandscape();return}
 if(document.fullscreenElement){try{document.exitFullscreen()}catch(e){}toast('已退出全屏');return}
 const el=visibleStage(),portrait=matchMedia('(orientation:portrait)').matches;
 const canFS=!!(el&&(el.requestFullscreen||el.webkitRequestFullscreen));
 /* 桌面横屏：优先标准全屏；失败或竖屏手机一律走 CSS 伪横屏 */
 if(!portrait&&canFS){
  try{
   const p=el.requestFullscreen?el.requestFullscreen():el.webkitRequestFullscreen();
   if(p&&p.then)p.then(()=>toast('⛶ 已全屏')).catch(()=>enterLandscape());
   else toast('⛶ 已全屏');
   return;
  }catch(e){}
 }
 enterLandscape();
}
