/* ================== v0.31 · 场景 / 构图 / 设置浮层 / 默认全屏背景 ================== */
/* 让 v0.11 旧代码里的 ART.scenes.h / .v 仍有值（指向阳台），再由本版覆盖为按关卡取图 */
ART.scenes.h=ART.scenes.balcony_h;ART.scenes.v=ART.scenes.balcony_v;
if(!state.frame)state.frame='auto';

/* SCENE_MAP / QUEST_FRAME 已前置 */
function curId(){const q=Q(state.active)||currentQuest();return q?q.id:1}
function sceneKey(){return SCENE_MAP[curId()]||'balcony'}
function sceneSrc(portrait){return ART.scenes[sceneKey()+'_'+(portrait?'v':'h')]||ART.scenes.balcony_h}
function frameOf(){return state.frame==='auto'?(QUEST_FRAME[curId()]||'full'):state.frame}
function applyFrame(){
 const st=$('#vnStage');if(!st)return;
 st.classList.remove('frame-half','frame-full');st.classList.add('frame-'+frameOf());
 const f=$('#frameSel');if(f)f.value=state.frame;
}
/* 覆盖按关卡 + 方向取全屏背景；伪横屏跟随旋转 */
function syncFullBg(forceH){
 const el=$('#fullBg');if(!el)return;
 const portrait=matchMedia('(orientation:portrait)').matches;
 el.src=sceneSrc(!(forceH||!portrait));
}
function sceneApply(){
 const bg=$('#vnStage .vn-bg');if(bg)bg.src=sceneSrc(matchMedia('(orientation:portrait)').matches);
 syncFullBg(document.body.classList.contains('ls-mode')||!matchMedia('(orientation:portrait)').matches);
 applyFrame();
}
/* 默认开启全屏背景：不论横屏竖屏都铺满 */
(function(){
 document.body.classList.add('bg-full');
 const b=$('#bgBtn');if(b){b.setAttribute('aria-pressed','true');b.textContent='🖼 背景：开';}
 syncFullBg(false);
})();
/* 包装 renderQuest：每次重建舞台后套用本关场景板与构图 */
(function(){
 const _rq=window.renderQuest;
 window.renderQuest=function(){_rq.apply(this,arguments);
  if($('#vnStage'))sceneApply();
 };
 const _el=window.enterLandscape;
 window.enterLandscape=function(){_el.apply(this,arguments);sceneApply();syncFullBg(true)};
 const _xl=window.exitLandscape;
 window.exitLandscape=function(){_xl.apply(this,arguments);sceneApply()};
})();
/* ---------------- 设置浮层：显眼关闭 / Esc / 遮罩 / 可拖动 / 可滚动 ---------------- */
function openSettings(){
 document.body.classList.add('settings-open');
 const p=$('#settingsPanel'),b=$('#settingsBtn');
 if(p)p.hidden=false;
 if(b){b.setAttribute('aria-expanded','true');b.textContent='⚙ 设置（开）';}
 try{$('#settingsClose').focus()}catch(e){}
}
function closeSettings(){
 document.body.classList.remove('settings-open');
 const p=$('#settingsPanel'),b=$('#settingsBtn');
 if(p)p.hidden=true;
 if(b){b.setAttribute('aria-expanded','false');b.textContent='⚙ 设置';}
 try{$('#settingsBtn').focus()}catch(e){}
}
function toggleSettings(){document.body.classList.contains('settings-open')?closeSettings():openSettings()}
(function(){
 const sb=$('#settingsBtn'),sc=$('#settingsClose'),sf=$('#settingsCloseFoot'),mask=$('#settingsMask');
 if(sb)sb.onclick=toggleSettings;
 if(sc)sc.onclick=closeSettings;
 if(sf)sf.onclick=closeSettings;
 if(mask)mask.onclick=closeSettings;
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.body.classList.contains('settings-open')){e.preventDefault();closeSettings()}});
 /* 标题栏拖动（pointer events，同时支持触摸） */
 const head=$('#settingsHead'),panel=$('#settingsPanel');
 if(head&&panel){
  let dragging=false,sx=0,sy=0,ox=0,oy=0;
  head.addEventListener('pointerdown',e=>{
   if(e.target.closest('button'))return;
   const r=panel.getBoundingClientRect();
   dragging=true;sx=e.clientX;sy=e.clientY;ox=r.left;oy=r.top;
   panel.style.left=ox+'px';panel.style.top=oy+'px';panel.style.right='auto';
   head.setPointerCapture(e.pointerId);e.preventDefault();
  });
  head.addEventListener('pointermove',e=>{
   if(!dragging)return;
   const w=panel.offsetWidth,h=panel.offsetHeight;
   const nx=Math.min(Math.max(0,ox+e.clientX-sx),Math.max(0,innerWidth-w));
   const ny=Math.min(Math.max(0,oy+e.clientY-sy),Math.max(0,innerHeight-Math.min(h,80)));
   panel.style.left=nx+'px';panel.style.top=ny+'px';
  });
  const stop=()=>{dragging=false};
  head.addEventListener('pointerup',stop);head.addEventListener('pointercancel',stop);
 }
 /* 角色构图切换 */
 const fs=$('#frameSel');
 if(fs)fs.onchange=()=>{state.frame=fs.value;save();applyFrame();toast('角色构图：'+({auto:'自动（按场景）',full:'全身',half:'半身 · 下半身没入气泡'})[state.frame])};
 /* 更多页面入口（原先在 tabs 里，现收进设置） */
 const mp=$('#morePagesBtn');
 if(mp)mp.onclick=()=>{const on=document.body.classList.toggle('more-pages');
  mp.setAttribute('aria-expanded',String(on));mp.textContent=on?'⋯ 收起更多页面':'⋯ 展开更多页面（时间线 / 换卡 / 画廊）';AE.sfx('select')};
 /* 语音关键词 */
 const _hv=window.handleVoice;
 window.handleVoice=function(t){
  if(/打开设置|设置界面/.test(t)){openSettings();return}
  if(/关闭设置|退出设置/.test(t)){closeSettings();return}
  if(/半身|上半身/.test(t)){state.frame='half';save();applyFrame();toast('已切半身构图');return}
  if(/全身/.test(t)){state.frame='full';save();applyFrame();toast('已切全身构图');return}
  return _hv.apply(this,arguments)};
})();
