/* ================== v0.31 · 极简主页 / 小判读 / 表情层 / 每轮素材规则 ================== */
/* ① 每轮固定生成素材（无需用户提醒）：本轮 5 张表情合页 → 10 个透明层，接入第 4–6 关 */
/* EXPR_QUESTS 已前置 */
function applyExpr(){
 const st=$('#vnStage');if(!st)return;
 const qid=curId();if(!EXPR_QUESTS.includes(qid))return;
 const ids=questCast(Q(state.active)||currentQuest());
 const els=[...st.querySelectorAll('.vn-actor, .vn-char')];
 ids.forEach((id,i)=>{
  const src=ART.expr&&ART.expr[id];const el=els[i];
  if(!src||!el)return;
  el.classList.add('expr-static');
  const imgs=el.querySelectorAll('img');
  if(imgs.length)imgs.forEach((im,k)=>{im.src=src;if(k>0)im.style.display='none'});
  else if(el.tagName==='IMG')el.src=src;
  const old=el.getAttribute('aria-label')||'';
  el.setAttribute('aria-label',old.replace('（双帧呼吸循环）','')+'（本关表情差分）');
 });
}
(function(){
 const _rq=window.renderQuest;
 window.renderQuest=function(){_rq.apply(this,arguments);if($('#vnStage'))applyExpr()};
 /* vnFeedback 之后不会重建舞台；切关时 renderQuest 会重新套用 */
})();

/* ② 「哈士喵的判读」改成小气泡，回到对白按钮收进气泡内 */
(function(){
 const _fb=window.vnFeedback;
 window.vnFeedback=function(html){
  const st=$('#vnStage'),box=$('#vnDialog');
  if(!box){return _fb.apply(this,arguments)}
  /* 先按原逻辑填文字（它会加 mode-choice），再改成 mode-feedback */
  _fb.apply(this,arguments);
  box.classList.remove('mode-choice');box.classList.add('mode-feedback');
  if(st)st.classList.add('feedback-mode');
  /* 原函数把「回到对白」插进了底部控制条，挪回小气泡内 */
  const old=$('#vnBack');if(old)old.remove();
  if(!box.querySelector('.vn-fb-back')){
   const b=document.createElement('button');b.type='button';b.className='vn-fb-back';
   b.textContent='↩ 回到对白';b.onclick=()=>{vnStep=0;vnRender()};
   box.appendChild(b);
  }
  const ctl=$('#vnCtl');if(ctl)ctl.querySelectorAll('#vnBack').forEach(x=>x.remove());
 };
 /* 非反馈态清掉反馈样式，避免下次对白还是小气泡 */
 const _vr=window.vnRender;
 window.vnRender=function(){
  const st=$('#vnStage'),box=$('#vnDialog');
  if(st)st.classList.remove('feedback-mode');
  if(box)box.classList.remove('mode-feedback');
  box&&box.querySelector('.vn-fb-back')&&box.querySelector('.vn-fb-back').remove();
  return _vr.apply(this,arguments);
 };
})();

/* ③ 主页大按钮随进度更新；折叠区默认收起 */
function refreshHome(){
 const done=state.cleared.length;
 const sub=$('#ctaSub');if(sub)sub.textContent=done?('继续 · 已通 '+done+' / 30 关'):'从第一关开始';
 const lp=$('#levelText'),et=$('#entryText');
 const hp=$('#homeProgress'),he=$('#homeEntries');
 if(hp&&lp)hp.textContent=lp.textContent;
 if(he&&et)he.textContent=et.textContent;
}
(function(){
 const _tab=window.tab;
 window.tab=function(t){const r=_tab.apply(this,arguments);if(t==='home')refreshHome();return r};
 if(typeof renderHome==='function'){const _rh=window.renderHome;window.renderHome=function(){_rh.apply(this,arguments);refreshHome()}}
 refreshHome();
})();

