/* ================== v0.31 · 通关自动给「下一话」 ================== */
function closeClear(){const c=$('#vnClear');if(c)c.remove()}
function goNextQuest(){
 const q=Q(state.active)||currentQuest(),n=q.id+1,nq=Q(n);
 closeClear();
 if(!nq){toast('全部主线已完成，啊呜！');tab('map');return}
 if(perfLocked(n)){toast('第 '+n+' 话的动画表演还在制作，敬请期待');tab('map');renderMap();return}
 openQuest(n);
}
function showClear(id){
 const q=Q(id);if(!q)return;
 const st=$('#vnStage');if(!st)return;
 closeClear();
 const n=q.id+1,nq=Q(n);
 const nextOk=nq&&!perfLocked(n);
 const un=q.unlocks.length?q.unlocks.map(x=>E(x)?.name||x).join('、'):'无新增';
 const nextLabel=!nq?'🏁 主线已走完':nextOk?('▶ 下一话 · 第 '+n+' 关'):('🔒 第 '+n+' 话还在制作');
 const box=document.createElement('div');
 box.id='vnClear';box.className='vn-clear';box.setAttribute('role','dialog');
 box.setAttribute('aria-label','第 '+q.id+' 关完成');
 box.innerHTML='<span class="cl-badge">✓ 本关完成</span>'
  +'<h3>第 '+q.id+' 话 · '+esc(q.title)+'</h3>'
  +'<p>解锁词条：<span class="cl-unlock">'+esc(un)+'</span></p>'
  +'<div class="cl-btns">'
  +'<button type="button" class="cl-next" onclick="'+(nextOk?'goNextQuest()':"tab('map')")+'">'+esc(nextLabel)+'</button>'
  +'<button type="button" onclick="tab(\'map\')">🗺 回关卡地图</button>'
  +'<button type="button" onclick="closeClear();vnStep=0;vnRender()">↺ 重看本话</button>'
  +'<button type="button" class="cl-stay" onclick="closeClear()">✕ 留在本话</button>'
  +'<button type="button" onclick="playShards('+q.id+')">🎮 资料碎片（可选）</button>'
 +'</div>';
 st.appendChild(box);
}
function playShards(id){closeClear();try{if(typeof mini!=='undefined'&&mini.start)mini.start(id);else toast('小游戏暂不可用')}catch(e){toast('小游戏暂不可用')}}
(function(){
 const _fq=window.finishQuest;
 window.finishQuest=function(id){
  const r=_fq.apply(this,arguments);
  /* renderQuest 会重建舞台 DOM，等一帧再挂卡片 */
  setTimeout(()=>showClear(id),140);
  return r;
 };
})();

