  s.w=Math.max(150,Math.min(sw,Number(s.w)||e.getBoundingClientRect().width));
  s.x=Math.max(0,Math.min(sw-s.w,Number(s.x)||0));   /* 左右绝不超出屏幕 */
  s.h=Math.max(50,Number(s.h)||e.getBoundingClientRect().height);
