  e.classList.add('v19-box');e.dataset.v19k=x.o.k;
  e.style.position='absolute';e.style.left=s.x+'px';e.style.top=s.y+'px';
  e.style.right='auto';e.style.bottom='auto';
  e.style.width=s.w+'px';e.style.height=(s.h>50?s.h+'px':'auto');
