var CORE19={cat:'./assets/26a9833e62abb10b.webp',gin:'./assets/8dfbead41d8eea1e.webp'};
var core19T={x:0,y:0,s:1.15};
function openCore19(which){
 var d=$('#core19');
 if(!d){
  d=document.createElement('div');d.id='core19';d.className='core19';
  d.innerHTML='<div class="core19-head"><b>📜 原作者设定原稿</b>'
   +'<button type="button" data-c="cat" class="on">眼镜猫三视图定稿</button>'
   +'<button type="button" data-c="gin">银时三视图（已退役归档）</button>'
   +'<button type="button" data-z="in">＋</button><button type="button" data-z="out">－</button>'
   +'<button type="button" data-z="reset">↺</button>'
   +'<button type="button" class="close" id="core19Close">✕ 关闭</button></div>'
   +'<div class="core19-frame" id="core19Frame"><img id="core19Img" alt="原作者设定原稿"></div>'
   +'<div class="core19-tip">可直接拖动 / 滚轮缩放查看细节；画面会被钳在方框内，不会拖出边框。原稿由原作者提供并授权使用。</div>';
  document.body.appendChild(d);
  d.querySelector('.core19-head').addEventListener('click',e=>{
   var b=e.target.closest('button');if(!b)return;
   if(b.id==='core19Close'){d.remove();return}
   if(b.dataset.c){core19Which=b.dataset.c;core19T={x:0,y:0,s:1.15};
    d.querySelectorAll('[data-c]').forEach(x=>x.classList.toggle('on',x===b));core19Apply();return}
   if(b.dataset.z==='in')core19T.s=Math.min(3.4,core19T.s*1.2);
   else if(b.dataset.z==='out')core19T.s=Math.max(1.15,core19T.s/1.2);
   else core19T={x:0,y:0,s:1.15};
   core19Apply();
  });
  var fr=d.querySelector('#core19Frame');
  fr.addEventListener('wheel',e=>{e.preventDefault();core19T.s=Math.max(1.15,Math.min(3.4,core19T.s*(1-e.deltaY*.0012)));core19Apply()},{passive:false});
  fr.addEventListener('pointerdown',e=>{
   core19Drag={x:e.clientX,y:e.clientY,x0:core19T.x,y0:core19T.y};
   try{fr.setPointerCapture(e.pointerId)}catch(err){}
  },{passive:true});
  fr.addEventListener('pointermove',e=>{
   if(!core19Drag)return;
   core19T.x=core19Drag.x0+(e.clientX-core19Drag.x);
   core19T.y=core19Drag.y0+(e.clientY-core19Drag.y);core19Apply();
  },{passive:true});
  fr.addEventListener('pointerup',()=>{core19Drag=null},{passive:true});
  fr.addEventListener('pointercancel',()=>{core19Drag=null},{passive:true});
 }
 core19Which=which||'cat';core19T={x:0,y:0,s:1.15};core19Apply();
}
var core19Which='cat',core19Drag=null;
function core19Apply(){
 var fr=$('#core19Frame'),im=$('#core19Img');if(!fr||!im)return;
 im.src=CORE19[core19Which]||CORE19.cat;
 var w=fr.clientWidth,h=fr.clientHeight;
 var nw=im.naturalWidth||900,nh=im.naturalHeight||506;
 core19T.s=Math.max(1.15,Math.min(3.4,core19T.s||1.15));
 var base=Math.max(w,h*nw/nh)*core19T.s;   /* 至少一个方向铺满方框 */
 im.style.width=base+'px';im.style.height='auto';
 var ih=base*nh/nw;
 if(!core19T.centered){core19T.x=(w-base)/2;core19T.y=(h-ih)/2;core19T.centered=true;}
 /* 钳死：图片永远覆盖方框，边缘不露白、不出框 */
 core19T.x=Math.max(w-base,Math.min(0,core19T.x));
 core19T.y=Math.max(h-ih,Math.min(0,core19T.y));
 im.style.transform='translate3d('+core19T.x+'px,'+core19T.y+'px,0)';
}
