/* ================== v0.33 · 统一 fitBox（借鉴 Konva fitContain / PixiJS Layout） ==================
   一个函数管所有「把贴图放进盒子」：contain 等比完整、居中；cover 才铺满裁切。
   新 DOM 出现时按分层规则自动套用，避免再出现某处漏改 cover 把角色切头切脚。 */
function fitBox(cw,ch,iw,ih,mode){
  mode=mode||'contain';
  if(!(cw>0&&ch>0&&iw>0&&ih>0))return {x:0,y:0,w:cw||0,h:ch||0,s:1};
  var sc=(mode==='cover')?Math.max(cw/iw,ch/ih):Math.min(cw/iw,ch/ih);
  var w=iw*sc,h=ih*sc;
  return {x:(cw-w)/2,y:(ch-h)/2,w:w,h:h,s:sc};
}
window.fitBox=fitBox;
var FIT_RULES={figure:'contain',expr:'contain',thumb:'contain',background:'cover'};
function classifyFitRole(im){
  if(!im||im.tagName!=='IMG')return null;
  var p=im.parentElement,pc=p?String(p.className||''):'',gp=p&&p.parentElement?String(p.parentElement.className||''):'';
  if(/case18-bg|vn-bg|fullBg/.test(String(im.className||''))||/asset-thumb scene/.test(gp)||/case18-th/.test(pc)&&p.getAttribute('data-kind')==='scene')return 'background';
  if(/case18-fg|stage-char|vn-char|vn-actor|char-btn|roster|asset-thumb charm|entry-art|lightbox18/.test(pc+' '+gp+' '+String(im.className||'')))return 'figure';
  if(/asset-thumb|case18-th|entry-art-th/.test(pc+' '+gp))return 'thumb';
  return null;
}
function applyFitRules(root){
  var scope=root&&root.querySelectorAll?root:document,list=scope.querySelectorAll('img');
  for(var i=0;i<list.length;i++){
    var im=list[i],role=classifyFitRole(im);
    if(!role)continue;
    var want=FIT_RULES[role]||LAYOUT_RULES.layers.figure;
    if(im.style.objectFit!==want){im.style.objectFit=want;im.dataset.fitRule=role;}
  }
}
var fitPending=false;
function scheduleFit(root){
  if(fitPending)return;fitPending=true;
  requestAnimationFrame(()=>{fitPending=false;try{applyFitRules(root||document.body)}catch(e){}});
}
if(window.MutationObserver){
  var fitObs=new MutationObserver(ms=>{
    for(var i=0;i<ms.length;i++){if(ms[i].addedNodes&&ms[i].addedNodes.length){scheduleFit(document.body);break;}}
  });
  try{fitObs.observe(document.body,{childList:true,subtree:true})}catch(e){}
}
document.addEventListener('DOMContentLoaded',()=>scheduleFit(document.body));
scheduleFit(document.body);
window.applyFitRules=applyFitRules;


