/* ② 语音包接口：对外 window.HuskyVoice
   - 只播放用户自行导入 / 注册的音频；没有任何片段时静默，绝不回落 TTS
   - 朗读默认关 ⇒ 全站零语音播报，读屏仍靠 aria-live 拿文字
   - 支持按「角色 + 情绪」注册，文件名约定见关于页 */
window.HuskyVoice=(function(){
  var clips={},idx={},evs={},vol=.9,enabled=true;
  var MOODS=['tap','happy','surprise','shy','calm','cool','spark','combo'];
  var MOOD_WORD={'点击':'tap','轻点':'tap','摸头':'tap','戳':'tap','tap':'tap','poke':'tap','click':'tap',
    '开心':'happy','笑':'happy','happy':'happy','smile':'happy','欢呼':'happy',
    '惊讶':'surprise','吓':'surprise','surprise':'surprise','吃惊':'surprise',
    '害羞':'shy','脸红':'shy','shy':'shy','蹭':'shy',
    '平静':'calm','温和':'calm','calm':'calm','嗯':'calm',
    '冷峻':'cool','生气':'cool','不爽':'cool','cool':'cool','哼':'cool',
    '电波':'spark','兴奋':'spark','spark':'spark','噼啪':'spark',
    '连击':'combo','连点':'combo','combo':'combo'};
  var NAME2ID={'茵蒂克丝':'index','上条当麻':'touma','御坂美琴':'misaka','导览员':'guide',
    '导览员 · 禁书目录':'guide','哈士喵':'base','本体':'base','一方通行':'accelerator',
    '结业馆长':'librarian','结业 · 禁书目录馆长':'librarian','白井黑子':'kuroko',
    '神裂火织':'kanzaki','史提尔':'styl','食蜂操祈':'shokuhou','欧提努斯':'othinus',
    '爱丽丝':'alice','垣根帝督':'kakine','麦野沉利':'mugino','滨面仕上':'hamazura',
    '右方之火':'rightfire','最后之作':'lastorder','土御门元春':'tsuchimikado',
    '上里翔流':'shangli','去鸣':'sakuyo','馆长':'librarian'};
  var IDWORD={'index':'茵蒂克丝','touma':'上条当麻','misaka':'御坂美琴','guide':'导览员','base':'哈士喵',
    'accelerator':'一方通行','librarian':'结业馆长','kuroko':'白井黑子','kanzaki':'神裂火织',
    'styl':'史提尔','shokuhou':'食蜂操祈','othinus':'欧提努斯','alice':'爱丽丝','kakine':'垣根帝督',
    'mugino':'麦野沉利','hamazura':'滨面仕上','rightfire':'右方之火','lastorder':'最后之作',
    'tsuchimikado':'土御门元春','shangli':'上里翔流','sakuyo':'去鸣'};
  function key(r,m){return String(r||'base')+'|'+String(m||'tap')}
  function norm(src){
    if(src&&typeof src==='object'&&typeof src.tagName==='string'&&src.tagName==='AUDIO')return src.src;
    if(typeof File!=='undefined'&&src instanceof File)return URL.createObjectURL(src);
    if(typeof Blob!=='undefined'&&src instanceof Blob)return URL.createObjectURL(src);
    return String(src);
  }
  function emit(e,p){(evs[e]||[]).forEach(function(f){try{f(p)}catch(_){}})}
  function roleOf(name){
    var s=String(name||'').toLowerCase();
    for(var k in NAME2ID)if(s.indexOf(k.toLowerCase())>=0)return NAME2ID[k];
    for(var id in IDWORD)if(s.indexOf(id)>=0)return id;
    return 'base';
  }
  function moodOf(name){
    var s=String(name||'').toLowerCase();
    for(var w in MOOD_WORD)if(s.indexOf(w)>=0)return MOOD_WORD[w];
    return 'tap';
  }
  var api={
    version:'v0.36',moods:MOODS.slice(),
    register:function(roleId,mood,src){
      var m=MOODS.indexOf(mood)>=0?mood:'tap',k=key(roleId,m),list=clips[k]=clips[k]||[];
      [].concat(src).forEach(function(x){list.push(norm(x))});
      emit('register',{roleId:roleId,mood:m,count:list.length});return list.length;
    },
    registerMany:function(map){var n=0;for(var r in map){for(var m in map[r]){n+=api.register(r,m,map[r][m])>0?1:0}}return n},
    has:function(roleId,mood){return !!(clips[key(roleId,mood)]||[]).length},
    list:function(){var o={};for(var k in clips)o[k]=clips[k].slice();return o},
    clear:function(roleId,mood){
      if(roleId==null){clips={};idx={};return}
      var pre=String(roleId)+'|';
      for(var k in clips)if(k.indexOf(pre)===0&&(mood==null||k===key(roleId,mood)))delete clips[k];
    },
    play:function(roleId,mood,opts){
      if(!enabled){emit('miss',{roleId:roleId,mood:mood,reason:'disabled'});return false}
      var list=clips[key(roleId,mood)];
      if(!list||!list.length)list=clips[key(roleId,'tap')];
      if(!list||!list.length)list=clips[key('base',mood)];
      if(!list||!list.length){emit('miss',{roleId:roleId,mood:mood});return false}
      try{if(window.speechSynthesis)window.speechSynthesis.cancel();speakQueue=[];speakBusy=false}catch(e){}
      var k=key(roleId,mood),i=(idx[k]=(idx[k]||0)+1)-1;
      if(opts&&opts.index!=null)i=opts.index;
      var src=list[((i%list.length)+list.length)%list.length],a=new Audio(src);
      var vv=(state&&state.vol)?(state.vol.master/100)*(state.vol.speak/100):vol;
      a.volume=Math.max(0,Math.min(1,vv*vol));
      a.onended=function(){emit('end',{roleId:roleId,mood:mood,src:src})};
      var pr=a.play();if(pr&&pr.catch)pr.catch(function(){emit('error',{roleId:roleId,mood:mood})});
      emit('play',{roleId:roleId,mood:mood,src:src,audio:a});return a;
    },
    on:function(e,f){(evs[e]=evs[e]||[]).push(f);return api},
    off:function(e,f){evs[e]=(evs[e]||[]).filter(function(x){return x!==f});return api},
    setVolume:function(v){vol=Math.max(0,Math.min(1,Number(v)||0));return api},
    getVolume:function(){return vol},
    setEnabled:function(b){enabled=!!b;return api},
    isEnabled:function(){return enabled},
    moodOf:moodOf,roleOf:roleOf,
    /* 供「🎧 导入语音包」调用：FileList → 按 角色_情绪 归户，同时注册到本接口 */
    attachFiles:function(files){
      var n=0,by={};[].slice.call(files||[]).forEach(function(f){
        if(!/^audio\//.test(f.type||'')&&!/\.(mp3|wav|ogg|m4a|aac|flac)$/i.test(f.name||''))return;
        var r=roleOf(f.name)||'base',m=moodOf(f.name),u=URL.createObjectURL(f);
        api.register(r,m,u);by[r]=1;n++;
      });
      emit('import',{count:n,roles:Object.keys(by).length});return n;
    }
  };
  return api;
})();

/* ②-b 导入 UI 扩展：原逻辑照跑（按角色归户 voicePack），再按情绪注册 HuskyVoice */
(function(){
  var inp=$('#packFiles');if(!inp)return;
  var old=inp.onchange;
  inp.onchange=function(e){
    var files=[].slice.call(e.target.files||[]);
    if(old)try{old.call(this,e)}catch(_){}
    var n=window.HuskyVoice.attachFiles(files);
    if(n)toast('🎧 已导入 '+n+' 段语音 · 点击台词可直接触发对应情绪');
  };
})();

