function pickTap36(roleId,st,stage){
  var now=Date.now();_tapHits36=_tapHits36.filter(function(t){return now-t<2400});
  _tapHits36.push(now);var combo=_tapHits36.length>=3;
  var pool;
  if(combo&&Math.random()<.72)pool=TAP_CTX36.combo;
  else if(stage==='choice'&&Math.random()<.26)pool=TAP_CTX36.choice;
  else if(stage==='feedback'&&Math.random()<.26)pool=TAP_CTX36.feedback;
  else if(Math.random()<.58&&TAP_ROLE36[roleId])pool=TAP_ROLE36[roleId];
  else pool=TAP_POOL36[st]||TAP_POOL36.warm;
  var it=pool[Math.floor(Math.random()*pool.length)]||['喵','happy'];
  if(it[0]===_lastTap36&&pool.length>1)it=pool[(pool.indexOf(it)+1)%pool.length];
  _lastTap36=it[0];
  var text=it[0].replace('×N','×'+Math.min(_tapHits36.length,9)),mood=combo?'combo':it[1];
  if(!combo&&Math.random()<.12){
    try{var w=String(currentWeather());var wp=TAP_CTX36.weather[w];if(wp&&wp.length){text=wp[0][0];mood=wp[0][1]}}catch(e){}
  }
  return {text:text,mood:mood,combo:combo,hits:_tapHits36.length};
}

