function tap36Bubble(stage,el,pick,ord){
  var S=stage.getBoundingClientRect(),R=el.getBoundingClientRect();
  if(!(S.width>0&&R.width>0))return;
  var olds=[].slice.call(stage.querySelectorAll('.vn-tap-bubble'));
  /* 组件互斥：每次点击的主气泡清掉旧的；连击第二条保留第一条 */
  if(ord===0)olds.forEach(function(x){x.remove()});
  var others=[].slice.call(stage.querySelectorAll('.vn-tap-bubble'));
  var b=document.createElement('div');b.className='vn-tap-bubble'+(pick.combo?' combo':'');
  var who=document.createElement('span');who.className='who';
  who.textContent=(ROLE_NAME36[tap36Role]||'哈士喵')+(pick.combo?' · 连击 ×'+Math.min(pick.hits,9):'');
  var im=document.createElement('img');im.className='stk';im.alt='';
  im.src=ART.stickers[STICKER36[pick.mood]||'heart'];
  var tx=document.createElement('span');tx.textContent=pick.text;
  b.appendChild(im);b.appendChild(who);b.appendChild(tx);
  b.style.visibility='hidden';b.style.maxWidth=Math.min(S.width*.62,300)+'px';stage.appendChild(b);
  var bw=b.offsetWidth,bh=b.offsetHeight;
  function rel(g){var q=g.getBoundingClientRect();return {l:q.left-S.left,t:q.top-S.top,r:q.right-S.left,b:q.bottom-S.top}}
  var guards=[].slice.call(stage.querySelectorAll('.vn-dialog,.vn-ctl,.vn-hud,.vn-nameplate,.vn-name')).map(rel);
  var hudB=0;guards.forEach(function(g){if(g.t<70)hudB=Math.max(hudB,g.b)});
  var minTop=Math.max(8,hudB+8);
  var blocks=guards.concat(others.map(rel));
  var relL=R.left-S.left,relR=R.right-S.left,relT=R.top-S.top;
  function clamp(v,a,z){return Math.max(a,Math.min(z,v))}
  function ov(a,c){return Math.max(0,Math.min(a.r,c.r)-Math.max(a.l,c.l))*Math.max(0,Math.min(a.b,c.b)-Math.max(a.t,c.t))}
  var cand=[
    [relL-bw-8,relT+16],[relR+8,relT+16],[(relL+relR)/2-bw/2,relT-bh-10],
    [8,relT+16],[S.width-bw-8,relT+16],[relL-bw-8,relT-bh-10],
    [8,minTop],[S.width-bw-8,minTop],[(relL+relR)/2-bw/2,minTop],
    [relL-bw-8,minTop],[relR+8,minTop]
  ];
  if(ord>0&&others.length){var o=rel(others[0]);cand.unshift([o.l,o.b+9])}
  var best=null,score=Infinity;
  cand.forEach(function(c){
    var l=clamp(c[0],8,Math.max(8,S.width-bw-8)),t=clamp(c[1],minTop,Math.max(minTop,S.height-bh-8));
    var box={l:l,t:t,r:l+bw,b:t+bh},pen=0;
    blocks.forEach(function(G){pen+=ov(box,G)});
    pen+=Math.abs(t-relT)*0.0002+Math.abs(l-(relL+relR)/2)*0.0001;
    if(pen<score){score=pen;best={l:l,t:t,pen:pen}}
  });
  b.style.left=Math.round(best.l)+'px';b.style.top=Math.round(best.t)+'px';b.style.visibility='visible';
  clearTimeout(b._t);
  b._t=setTimeout(function(){b.classList.add('out');setTimeout(function(){b.remove()},400)},pick.combo?2100:2600);
}
